const SAVE_KEY = 'gore-wars-save-v1';
const defaultState = {name:'Nora Vale',playerId:null,role:'player',avatarUrl:null,avatarModeration:'none',faction:null,ownerGrants:[],level:3,xp:62,cash:840,stamina:72,maxStamina:100,nerve:21,maxNerve:30,vitality:86,maxVitality:100,morale:78,heat:12, power:14,resilience:12,reflexes:11,precision:10, inventory:[{id:'lockpick',name:'Harbor lockpick',icon:'⚿',qty:1,rarity:'Uncommon'},{id:'bandage',name:'Field wrap',icon:'✚',qty:2,rarity:'Common'},{id:'shells',name:'9mm shells',icon:'◈',qty:18,rarity:'Common'}], crimes:0, trained:0, completedMissions:0, selectedDistrict:'Rustwater Docks', activity:[{icon:'◆',title:'Welcome to Blackharbor',desc:'Your safehouse is ready in Rustwater Docks.',time:'Just now'},{icon:'⌖',title:'District intel updated',desc:'Ashmarket has a new opportunity.',time:'Today'}]};
function generatePlayerId(){return String(Math.floor(1000000+Math.random()*8999999))}
function load(){try{const saved={...defaultState,...JSON.parse(localStorage.getItem(SAVE_KEY)||'{}')};saved.playerId ||= generatePlayerId();saved.accountCreatedAt ||= Date.now();if(!Array.isArray(saved.activity))saved.activity=defaultState.activity.slice();if(!Array.isArray(saved.inventory))saved.inventory=defaultState.inventory.map(i=>({...i}));if(!Array.isArray(saved.ownerGrants))saved.ownerGrants=[];if(saved.faction&&!Array.isArray(saved.faction.invites))saved.faction.invites=[];return saved}catch{return {...defaultState,playerId:generatePlayerId(),activity:defaultState.activity.slice(),inventory:defaultState.inventory.map(i=>({...i})),ownerGrants:[],accountCreatedAt:Date.now()}}}
let state = load(); let publicProfileId=new URLSearchParams(location.search).get('XID'); let view = publicProfileId?'publicProfile':'overview'; let selectedShop = null;
const AUTH_KEY = 'gore-wars-auth-v1';
let activePlayerId = null;
const TRAINING_STATS = ['power','resilience','reflexes','precision'];
const STAMINA_INTERVAL = 60000; // One stamina per minute, including time away.
const PLAYER_INDEX_KEY='gore-wars-players-v1';
function playerSaveKey(id){return SAVE_KEY+':player:'+id}
function readPlayerIndex(){try{const list=JSON.parse(localStorage.getItem(PLAYER_INDEX_KEY)||'[]');return Array.isArray(list)?list:[]}catch{return[]}}
function registerPlayer(player){const list=readPlayerIndex();const record={playerId:String(player.playerId),name:player.name||'Operative',level:Number(player.level||3),xp:Number(player.xp||0),faction:player.faction?.name||'Unaffiliated',avatarUrl:player.avatarUrl||player.picture||null,lastSeenAt:Date.now()};const i=list.findIndex(x=>x.playerId===record.playerId);if(i<0)list.push(record);else list[i]={...list[i],...record};localStorage.setItem(PLAYER_INDEX_KEY,JSON.stringify(list.slice(-5000)))}
function findPlayer(id){if(String(id)===String(state.playerId))return {playerId:state.playerId,name:state.name,level:state.level,xp:state.xp,faction:state.faction?.name||'Unaffiliated',avatarUrl:state.avatarUrl};return readPlayerIndex().find(p=>String(p.playerId)===String(id))}

function save(){if(activePlayerId){checkpointPresence();registerPlayer(state);localStorage.setItem(playerSaveKey(activePlayerId),JSON.stringify(state))}}
function restorePlayer(player){
 const key=playerSaveKey(player.playerId);
 let saved=null;
 try{saved=JSON.parse(localStorage.getItem(key)||'null')}catch{}
 if(!saved){try{const legacy=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(String(legacy?.playerId)===String(player.playerId))saved=legacy}catch{}}
 state={...structuredClone(defaultState),...(saved||{}),name:player.name,playerId:player.playerId,role:player.role||'player'};
 state.accountCreatedAt ||= Date.now();
 closeSavedPresence(state);
 for(const stat of [...TRAINING_STATS,'trained','xp'])if(!Number.isFinite(state[stat])||state[stat]<0)state[stat]=defaultState[stat];
 if(!Array.isArray(state.activity))state.activity=[];
 if(!Array.isArray(state.inventory))state.inventory=[];
 activePlayerId=String(player.playerId);
 registerPlayer({...player,...state});
 recoverStamina();startPresence();save();
}
function closeSavedPresence(saved){
 const last=Number(saved.lastSeenAt)||Number(saved.onlineSince)||Date.now();
 if(saved.onlineSince){const seconds=Math.max(0,Math.floor((last-Number(saved.onlineSince))/1000));saved.onlineSeconds=(Number(saved.onlineSeconds)||0)+seconds;saved.presenceLog=Array.isArray(saved.presenceLog)?saved.presenceLog:[];saved.presenceLog.push({status:'offline',at:last,durationSeconds:seconds});}
 saved.onlineSince=null;saved.lastSeenAt=last;saved.presenceLog=(Array.isArray(saved.presenceLog)?saved.presenceLog:[]).slice(-40);
}
function startPresence(){state.onlineSince=Date.now();state.lastSeenAt=state.onlineSince;state.presenceLog=Array.isArray(state.presenceLog)?state.presenceLog:[];state.presenceLog.push({status:'online',at:state.onlineSince});state.presenceLog=state.presenceLog.slice(-40)}
function checkpointPresence(now=Date.now()){if(!activePlayerId||!state.onlineSince)return;const seconds=Math.max(0,Math.floor((now-state.onlineSince)/1000));if(seconds){state.onlineSeconds=(Number(state.onlineSeconds)||0)+seconds;state.onlineSince=now}state.lastSeenAt=now}
function endPresence(){if(!activePlayerId||!state.onlineSince)return;const now=Date.now();const seconds=Math.max(0,Math.floor((now-state.onlineSince)/1000));state.onlineSeconds=(Number(state.onlineSeconds)||0)+seconds;state.lastSeenAt=now;state.presenceLog=Array.isArray(state.presenceLog)?state.presenceLog:[];state.presenceLog.push({status:'offline',at:now,durationSeconds:seconds});state.presenceLog=state.presenceLog.slice(-40);state.onlineSince=null;save()}
function recoverStamina(now=Date.now()){
 if(!Number.isFinite(state.maxStamina)||state.maxStamina<=0)state.maxStamina=100;
 if(!Number.isFinite(state.stamina))state.stamina=defaultState.stamina;
 state.stamina=Math.max(0,Math.min(state.maxStamina,state.stamina));
 if(!Number.isFinite(state.staminaUpdatedAt)||state.staminaUpdatedAt>now)state.staminaUpdatedAt=now;
 if(state.stamina>=state.maxStamina){state.staminaUpdatedAt=now;return false}
 const ticks=Math.floor((now-state.staminaUpdatedAt)/STAMINA_INTERVAL);
 if(ticks<1)return false;
 state.stamina=Math.min(state.maxStamina,state.stamina+ticks);
 state.staminaUpdatedAt=state.stamina===state.maxStamina?now:state.staminaUpdatedAt+ticks*STAMINA_INTERVAL;
 return true;
}
function itemAsset(name){return 'assets/items/'+name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'.png'}
function accountAge(){const seconds=(Number(state.onlineSeconds)||0)+(state.onlineSince?Math.max(0,Math.floor((Date.now()-state.onlineSince)/1000)):0);const days=Math.floor(seconds/86400);if(days)return `${days} day${days===1?'':'s'}`;const hours=Math.floor(seconds/3600);const mins=Math.floor((seconds%3600)/60);return `${hours}h ${mins}m`}
function presenceLog(){return (state.presenceLog||[]).slice(-8).reverse().map(x=>`<div class="list-row"><div><strong>${x.status==='online'?'Online':'Offline'}</strong><span>${new Date(x.at).toLocaleString()}${x.durationSeconds?` · ${Math.floor(x.durationSeconds/3600)}h ${Math.floor((x.durationSeconds%3600)/60)}m`:''}</span></div><span class="tag ${x.status==='online'?'green':''}">${x.status}</span></div>`).join('')||'<div class="empty">No presence history yet.</div>'}
function isOwner(){return state.role==='owner'}
function money(n){return `${n.toLocaleString()} cr`}
function walletLabel(){return isOwner()?'UNLIMITED cr':money(state.cash)}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.getElementById('toasts').append(el);setTimeout(()=>el.remove(),3200)}
function addActivity(icon,title,desc){state.activity.unshift({icon,title,desc,time:'Just now'});state.activity=state.activity.slice(0,6)}
function spend(kind,amount){if(state[kind]<amount){toast(`You need more ${kind==='stamina'?'Stamina':'Nerve'}.`);return false}state[kind]-=amount;return true}
const districts=[['Rustwater Docks','10%','left:8%;top:52%'],['The Cut','25%','left:26%;top:29%'],['Ashmarket','18%','left:45%;top:54%'],['Crown Heights','5%','left:66%;top:17%'],['Glass Row','12%','left:74%;top:44%'],['Lowfield','35%','left:18%;top:76%'],['The Sprawl','42%','left:43%;top:78%'],['Foundry Ward','28%','left:59%;top:70%'],['Saint Vey','8%','left:80%;top:70%'],['Neon Mile','21%','left:67%;top:87%'],['Quarry Reach','48%','left:5%;top:15%'],['Warden’s Gate','30%','left:87%;top:20%']];
const shopLocations=[['01_ironline-armory','Ironline Armory','Foundry Ward','Equipment'],['02_bastion-supply','Bastion Supply','Warden’s Gate','Equipment'],['03_dockside-general','Dockside General','Rustwater Docks','Supplies'],['04_signal-house','Signal House','Glass Row','Equipment'],['05_glass-row-jewelers','Glass Row Jewelers','Glass Row','Lifestyle & Collectibles'],['06_redline-parts','Redline Parts','Foundry Ward','Vehicles & Travel'],['07_saint-vey-pharmacy','Saint Vey Pharmacy','Saint Vey','City Services'],['08_blackharbor-post','Blackharbor Post','Ashmarket','City Services'],['09_inkhouse-printworks','Inkhouse Printworks','The Cut','Supplies'],['10_quarry-recycling','Quarry Recycling','Quarry Reach','City Services'],['11_sweet-static','Sweet Static','Neon Mile','Lifestyle & Collectibles'],['12_nightshift-outfitters','Nightshift Outfitters','The Cut','Lifestyle & Collectibles'],['13_the-iron-vault','The Iron Vault','Foundry Ward','Equipment'],['14_rustwater-salvage','Rustwater Salvage','Rustwater Docks','City Services'],['15_last-chance-pawn','Last Chance Pawn','Lowfield','Markets & Trading'],['16_ashmarket-exchange','Ashmarket Exchange','Ashmarket','Markets & Trading'],['17_blackharbor-bazaar','Blackharbor Bazaar','Ashmarket','Markets & Trading'],['18_crown-auction-house','Crown Auction House','Crown Heights','Markets & Trading'],['19_mourning-bloom','Mourning Bloom','Saint Vey','Lifestyle & Collectibles'],['20_the-paper-lantern','The Paper Lantern','Saint Vey','Lifestyle & Collectibles'],['21_odd-company','Odd Company','Neon Mile','Lifestyle & Collectibles'],['22_the-collector-s-room',"The Collector's Room",'Crown Heights','Lifestyle & Collectibles'],['23_night-owl-grocer','Night Owl Grocer','The Sprawl','Supplies'],['24_chrome-row-motors','Chrome Row Motors','Glass Row','Vehicles & Travel'],['25_rustwater-chandlery','Rustwater Chandlery','Rustwater Docks','Vehicles & Travel'],['26_voss-estate','Voss Estate','Crown Heights','Finance & Property'],['27_blackharbor-bank','Blackharbor Bank','Glass Row','Finance & Property'],['28_blackharbor-museum','Blackharbor Museum','Saint Vey','Lifestyle & Collectibles'],['29_saint-vey-hall','Saint Vey Hall','Saint Vey','City Services'],['30_city-archives','City Archives',"Warden's Gate",'City Services'],['31_blackharbor-visitor-center','Blackharbor Visitor Center','Ashmarket','City Services'],['32_the-veil-market','The Veil Market','Overseas Network','Vehicles & Travel']];
function resourceCard(label,value,max,cls,meta){return `<div class="resource-hud-row"><div class="resource-hud-name"><b>${label}</b><span>${meta||'READY'}</span></div><div class="resource-hud-value"><strong>${value}</strong><span>/${max}</span></div><div class="resource-hud-bar ${cls||''}"><i style="width:${Math.min(100,value/max*100)}%"></i></div></div>`}
function layout(content,eyebrow,title,subtitle){return `<div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p>${content}`}
function overview(){return layout(`<section class="hero card"><div class="hero-art"></div><div class="hero-copy"><div class="eyebrow">BLACKHARBOR // RUSTWATER DOCKS</div><h2>The city remembers every debt.</h2><p>Keep your head down, read the angles, and build a name that opens locked doors.</p><button class="btn" data-view="crimes">Choose tonight’s move →</button></div></section><div class="resource-hud card" style="margin-top:16px"><div class="resource-hud-title"><span>OPERATIVE STATUS</span><small>SERVER SYNCED · UTC</small></div>${resourceCard('Stamina',state.stamina,state.maxStamina,'blue')}${resourceCard('Nerve',state.nerve,state.maxNerve,'gold')}${resourceCard('Vitality',state.vitality,state.maxVitality,'')}${resourceCard('Morale',state.morale,100,'gold')}</div><div class="grid grid-2"><section><div class="section-head"><h2>Open threads</h2><p>Two actions waiting</p></div><div class="list"><div class="list-row"><div><strong>Night shift at the docks</strong><span>Earn 140 cr · 45 min remaining</span></div><span class="tag green">Working</span></div><div class="list-row"><div><strong>Silas Quill’s introduction</strong><span>Visit Ashmarket to unlock the broker</span></div><button class="btn secondary" data-view="missions">View</button></div></div><div class="section-head"><h2>Recent activity</h2><p>Server log · synced</p></div><div class="card activity">${state.activity.map(a=>`<div class="activity-row"><div class="activity-icon">${a.icon}</div><div><strong>${a.title}</strong><span>${a.desc} · ${a.time}</span></div></div>`).join('')}</div></section><aside><div class="section-head"><h2>City pulse</h2><p>03 Oct 2026 · 21:14</p></div><div class="card"><div class="label">District heat</div><div class="metric">Ashmarket <small>+18% activity</small></div><p style="color:var(--muted);font-size:12px">A courier convoy arrives before midnight. The window is short.</p><button class="btn secondary" data-view="city">Read district intel</button></div><div class="section-head"><h2>Next milestone</h2></div><div class="card"><div class="label">Level ${state.level+1}</div><div class="metric">${state.xp} <small>/ 100 XP</small></div><div class="meter"><i style="width:${state.xp}%"></i></div><p style="color:var(--muted);font-size:11px;margin-bottom:0">Keep moving to unlock the Cut’s specialist gym.</p></div></aside></div>`, 'Welcome back, operative', state.name, 'Your safehouse is quiet. The city is not.');}
function profile(){const owner=state.role==='owner';const avatar=state.avatarUrl?`<img class="avatar-image" src="${state.avatarUrl}" alt="${state.name} avatar"/>`:`<div class="portrait-large">${state.name.slice(0,2).toUpperCase()}</div>`;return layout(`<div class="profile-identity"><div class="presence-dot online" title="Online"><span class="sr-only">Online</span></div><div><h2>${state.name} <span>[${state.playerId}]</span></h2><p>“Build your name. Take the city.”</p></div><span class="tag ${owner?'green':''}">${owner?'OWNER':'ONLINE NOW'}</span></div><div class="profile-grid"><section class="card profile-portrait">${avatar}<input id="avatarInput" type="file" accept="image/jpeg,image/png,image/webp" hidden/><label class="btn secondary" for="avatarInput">Change avatar</label><small class="avatar-help">666 × 916 output · JPG, PNG, or WebP · max 5 MB</small>${state.avatarModeration==='pending'?'<span class="tag">Pending safety review</span>':''}</section><section class="card profile-core"><div class="panel-title">Core information</div><div class="profile-level"><strong>Level ${state.level}</strong><span>${state.xp} / 100 XP</span></div><div class="meter"><i style="width:${state.xp}%"></i></div>${resourceCard('Stamina',state.stamina,state.maxStamina,'blue')}${resourceCard('Nerve',state.nerve,state.maxNerve,'gold')}${resourceCard('Vitality',state.vitality,state.maxVitality,'red')}${resourceCard('Morale',state.morale,100,'yellow')}</section><section class="card profile-actions"><div class="panel-title">Actions</div><div class="action-grid"><button class="btn secondary" disabled>Send message</button><button class="btn secondary" disabled>Add friend</button><button class="btn secondary" disabled>View faction</button><button class="btn secondary" disabled>Report player</button></div><p class="muted-note">Social actions will unlock as the authenticated player service is connected.</p></section></div><div class="profile-columns"><section class="card"><div class="panel-title">Basic information</div><dl class="profile-list"><dt>Player ID</dt><dd>${state.playerId}</dd><dt>Name</dt><dd>${state.name}</dd><dt>Role</dt><dd>${owner?'Game owner':'Operative'}</dd><dt>Faction</dt><dd>Unaffiliated</dd><dt>Job</dt><dd>New blood</dd><dt>Property</dt><dd>Temporary room</dd><dt>Relationship</dt><dd>Single</dd><dt>Account age</dt><dd>${accountAge()}</dd><dt>Presence history</dt><dd><div class="list">${presenceLog()}</div></dd></dl></section><section class="card"><div class="panel-title">Recent activity <span class="panel-link">View all</span></div><div class="activity">${state.activity.slice(0,5).map(a=>`<div class="activity-row"><div class="activity-icon">${a.icon}</div><div><strong>${a.title}</strong><span>${a.desc} · ${a.time}</span></div></div>`).join('')}</div></section></div><div class="profile-columns"><section class="card"><div class="panel-title">Honors & medals</div><div class="honor-row"><span>◆</span><span>New arrival</span><span>▣</span><span>First steps</span><span>?</span><span>Locked</span></div></section><section class="card"><div class="panel-title">Competition status</div><div class="empty">No active competitions enrolled. Visit Events when a seasonal competition opens.</div></section></div>`, 'Character // Profile', `${state.name} [${state.playerId}]`, 'One identity. One history. Every move counts.');}
function ensureFactionData(){const f=state.faction;if(!f.armory)f.armory=[{name:'Enhancers',type:'Utility',qty:0},{name:'Tools',type:'Utility',qty:0},{name:'Materials',type:'Utility',qty:0},{name:'Cesium-137',type:'Restricted material',qty:0}];if(!f.coreUpgrades)f.coreUpgrades=[{name:'Member capacity',desc:'Increase maximum members',level:1},{name:'Armory upgrades',desc:'Increase storage and lending limits',level:1},{name:'Dirty bomb lab',desc:'Unlock bomb production',level:0},{name:'Territory upgrades',desc:'Improve control and income',level:0},{name:'Chaining upgrades',desc:'Link organized crimes',level:0}];if(!f.specialTrees)f.specialTrees=['Logistics','Enforcement','Finance','Sabotage','Recruitment','Warfare','Smuggling','Intel'];if(!f.activeTrees)f.activeTrees=f.specialTrees.slice(0,6);if(!f.chat)f.chat=[];if(!f.newsletters)f.newsletters=[];if(!f.territory)f.territory='Rustwater Docks';if(f.territoryControl==null)f.territoryControl=18;if(f.respect==null)f.respect=0;save()}
function factions(){if(!state.faction)return layout('<div class="card faction-create"><div class="eyebrow">FACTIONS // FOUNDING</div><h2>Create your faction</h2><p>Founding creates a persistent player organization with you as founder. The one-time creation fee is <strong>15,000,000 cr</strong>.</p><div class="resource"><span>Your wallet</span><b>'+walletLabel()+'</b></div><div class="form-row"><input id="factionName" class="name-input" maxlength="32" placeholder="Faction name"><input id="factionTag" class="name-input" maxlength="5" placeholder="Tag"><button class="btn" id="createFaction" '+(!isOwner()&&state.cash<15000000?'disabled':'')+'>Create faction</button></div>'+(!isOwner()&&state.cash<15000000?'<p class="muted-note">You need 15,000,000 cr in exposed cash before founding a faction. Banked or protected funds do not count.</p>':'')+'</div>', 'Competition // Factions', 'Find your people.', 'Factions are player-created organizations with invitations, roles, treasury rules, and shared goals.');
ensureFactionData();const f=state.faction;const tab=window.factionTab||'overview';const tabs=[['overview','Overview'],['armory','Armory'],['upgrades','Upgrades'],['controls','Controls'],['communication','Communication'],['territory','Territory & Crimes']];let body='';
if(tab==='overview')body='<div class="grid grid-2"><section class="card"><div class="panel-title">Faction overview</div><p class="muted-note">Founded by '+state.name+' ['+state.playerId+'] · Founder</p><div class="resource"><span>Treasury</span><b>'+money(f.treasury)+'</b></div><div class="resource"><span>Members</span><b>'+(1+f.invites.length)+'</b></div><div class="resource"><span>Territory</span><b>'+(f.territory||'Rustwater Docks')+'</b></div></section><section class="card"><div class="panel-title">Recruitment</div><p class="muted-note">Invite players by their stable public ID. Invitations remain pending until accepted.</p><div class="form-row"><input id="invitePlayerId" class="name-input" placeholder="Player ID e.g. 3544082"><button class="btn" id="inviteBtn">Send invite</button></div><div class="list">'+(f.invites||[]).map(i=>'<div class="list-row"><div><strong>'+i.playerId+'</strong><span>Pending invitation</span></div><span class="tag">Pending</span></div>').join('')||'<div class="empty">No invitations sent yet.</div>'+'</div></section></div>';
if(tab==='armory')body='<div class="card"><div class="panel-title">Utility armory</div><p class="muted-note">Store Enhancers, Tools, Materials, and Cesium-137. Sports Sneakers are excluded by design.</p><div class="list">'+f.armory.map(i=>'<div class="list-row"><div><strong>'+i.name+'</strong><span>'+i.type+' · Balance '+i.qty+'</span></div><span class="tag">Loan / Give</span></div>').join('')+'</div><div class="form-row faction-action-row"><select id="armoryItem" class="name-input">'+f.armory.map(i=>'<option value="'+i.name+'">'+i.name+'</option>').join('')+'</select><input id="armoryQty" class="name-input" inputmode="numeric" placeholder="Qty"><select id="armoryMode" class="name-input"><option>Loan</option><option>Give</option></select><input id="armoryPlayer" class="name-input" placeholder="Member ID"><button class="btn" id="armoryAction">Loan item</button></div></div>';
if(tab==='upgrades')body='<div class="grid grid-2"><section class="card"><div class="panel-title">Core branch <span class="tag">Permanent</span></div><p class="muted-note">These upgrades are irreversible once purchased.</p><div class="list">'+f.coreUpgrades.map(u=>'<div class="list-row"><div><strong>'+u.name+'</strong><span>'+u.desc+' · Level '+u.level+'</span></div><button class="btn upgrade-btn" data-upgrade="'+u.name+'">Upgrade</button></div>').join('')+'</div></section><section class="card"><div class="panel-title">Special upgrades branch</div><p class="muted-note">Select up to 6 trees from 8 options. Loadouts can be swapped instantly.</p><div class="upgrade-trees">'+f.specialTrees.map(t=>'<button class="tag '+(f.activeTrees.includes(t)?'green':'')+' tree-btn" data-tree="'+t+'">'+t+'</button>').join('')+'</div><p class="muted-note">Active '+f.activeTrees.length+' / 6</p></section></div>';
if(tab==='controls')body='<div class="grid grid-2"><section class="card"><div class="panel-title">Faction profile</div><div class="form-row"><input id="factionBio" class="name-input" value="'+(f.bio||'')+'" placeholder="Faction motto or profile"><button class="btn" id="saveFactionProfile">Save</button></div><div class="panel-title controls-spaced">Permissions</div><div class="form-row"><input id="permissionPlayer" class="name-input" placeholder="Member ID"><select id="permissionRole" class="name-input"><option>Member</option><option>Officer</option><option>Co-Leader</option></select><button class="btn" id="setPermission">Save role</button></div></section><section class="card"><div class="panel-title">Give to user</div><p class="muted-note">Distribute faction vault funds or points to a member.</p><div class="form-row"><input id="factionGivePlayer" class="name-input" placeholder="Member ID"><input id="factionGiveAmount" class="name-input" inputmode="numeric" placeholder="Credits"><button class="btn" id="factionGiveBtn">Give</button></div><div class="panel-title controls-spaced">Newsletter</div><div class="form-row"><input id="newsletterText" class="name-input" placeholder="Announcement"><button class="btn" id="newsletterBtn">Publish</button></div><div class="panel-title controls-spaced">Dirty bomb lab</div><button class="btn" id="dirtyBombBtn">Create dirty bomb</button><span class="muted-note"> Lab level '+f.coreUpgrades.find(u=>u.name==='Dirty bomb lab').level+'</span></section></div>';
if(tab==='communication')body='<div class="card"><div class="panel-title">Faction chatbox</div><div class="faction-chat">'+(f.chat||[]).map(m=>'<div class="chat-line"><strong>['+m.playerId+']</strong> '+m.text+' <span>'+m.time+'</span></div>').join('')||'<div class="empty">No messages yet. Coordinate your next crime.</div>'+'</div><div class="form-row"><input id="factionChatInput" class="name-input" placeholder="Message your faction"><button class="btn" id="factionChatBtn">Send</button></div><div class="section-head"><h2>Newsletters</h2></div><div class="list">'+(f.newsletters||[]).map(n=>'<div class="list-row"><div><strong>'+n.text+'</strong><span>'+n.time+'</span></div><span class="tag">Announcement</span></div>').join('')||'<div class="empty">No newsletters published.</div>'+'</div></div>';
if(tab==='territory')body='<div class="grid grid-2"><section class="card faction-territory"><div class="panel-title">Territory map</div><div class="territory-map"><span class="territory-node selected">'+(f.territory||'Rustwater Docks')+'</span><span class="territory-node">Ashmarket</span><span class="territory-node">The Cut</span></div><div class="resource"><span>Control</span><b>'+f.territoryControl+'%</b></div></section><section class="card"><div class="panel-title">Organized crimes</div><div class="list"><div class="list-row"><div><strong>Dockside extraction</strong><span>Generates cash and respect from faction perks</span></div><button class="btn" id="startOcBtn">Start OC</button></div><div class="list-row"><div><strong>Ranked wars</strong><span>Compete for territory and seasonal rewards</span></div><button class="btn secondary" id="startRwBtn">Queue RW</button></div></div><div class="resource"><span>Faction cash</span><b>'+money(f.treasury)+'</b></div><div class="resource"><span>Faction respect</span><b>'+f.respect+'</b></div></section></div>';
return layout('<div class="card faction-banner"><div class="eyebrow">FACTION // '+f.tag+'</div><h2>'+f.name+'</h2><p>'+(f.bio||'Build a crew, then give it something worth defending.')+'</p></div><div class="faction-tabs">'+tabs.map(t=>'<button class="btn '+(tab===t[0]?'active':'secondary')+' faction-tab" data-faction-tab="'+t[0]+'">'+t[1]+'</button>').join('')+'</div>'+body,'Competition // Factions',f.name,'Management hub · '+tab);}
function ownerCheats(){if(!isOwner()){view='overview';return overview()}return layout(`<div class="card owner-console"><div class="eyebrow">OWNER // ADMIN CONSOLE</div><h2>Game owner controls</h2><p>Owner mode has an unlimited credit wallet. Grants are recorded here by recipient player ID for the connected account service.</p><div class="resource"><span>Your wallet</span><b>UNLIMITED cr</b></div><div class="form-row"><input id="grantPlayerId" class="name-input" inputmode="numeric" maxlength="7" placeholder="Recipient player ID e.g. 3544082"/><input id="grantAmount" class="name-input" inputmode="numeric" placeholder="Amount of credits"/><button class="btn" id="grantBtn">Give credits</button></div><p class="muted-note">Use whole positive credits only. This owner action is restricted to the verified owner role.</p><div class="section-head"><h2>Recent grants</h2><p>${state.ownerGrants.length} recorded</p></div><div class="list">${state.ownerGrants.map(g=>`<div class="list-row"><div><strong>${g.amount.toLocaleString()} cr → [${g.playerId}]</strong><span>${g.grantedAt}</span></div><span class="tag green">Granted</span></div>`).join('')||'<div class="empty">No owner grants yet.</div>'}</div></div>`, 'Owner // Cheats', 'Unlimited authority.', 'Grant credits to any player by their public ID.');}
function createFaction(){const name=document.getElementById('factionName')?.value.trim();const tag=document.getElementById('factionTag')?.value.trim().toUpperCase();if(state.faction){toast('You already lead a faction.');return}if(!name||name.length<3||name.length>32){toast('Faction name must be 3–32 characters.');return}if(!/^[A-Z0-9]{2,5}$/.test(tag)){toast('Faction tag must be 2–5 letters or numbers.');return}if(!isOwner()&&state.cash<15000000){toast('You need 15,000,000 cr in exposed cash.');return}if(!isOwner())state.cash-=15000000;state.faction={name,tag,treasury:15000000,invites:[],founderId:state.playerId};addActivity('⚑','Faction founded',`${name} [${tag}] · 15,000,000 cr founding fee`);save();render();toast(`${name} founded. 15,000,000 cr paid.`)}
function inviteToFaction(){if(!state.faction){toast('Create a faction first.');return}const input=document.getElementById('invitePlayerId');const playerId=input?.value.trim();if(!/^\d{7}$/.test(playerId)){toast('Enter a valid 7-digit player ID.');return}if(playerId===String(state.playerId)){toast('You cannot invite yourself.');return}if(state.faction.invites.some(i=>i.playerId===playerId)){toast('That player already has a pending invite.');return}state.faction.invites.push({playerId,invitedAt:new Date().toISOString()});addActivity('✉','Faction invite sent',`Invitation sent to player [${playerId}]`);save();render();toast(`Invite sent to [${playerId}].`)}
function factionAction(){ensureFactionData();const item=state.faction.armory.find(i=>i.name===document.getElementById('armoryItem')?.value);const qty=Number(document.getElementById('armoryQty')?.value);const playerId=document.getElementById('armoryPlayer')?.value.trim();if(!item||!Number.isSafeInteger(qty)||qty<=0||!/^\d{7}$/.test(playerId)){toast('Enter a valid item, quantity, and member ID.');return}if(item.name==='Sports Sneakers'){toast('Sports Sneakers cannot be stored in the utility armory.');return}if(item.qty<qty){toast('The armory does not have enough of that item.');return}item.qty-=qty;const mode=document.getElementById('armoryMode')?.value||'Loan';addActivity('⚑','Armory '+mode.toLowerCase()+' recorded',qty+' '+item.name+' → ['+playerId+']');save();render();toast(qty+' '+item.name+' '+(mode==='Give'?'given':'loaned')+' to ['+playerId+'].')}
function factionUpgrade(name){ensureFactionData();const u=state.faction.coreUpgrades.find(x=>x.name===name);if(!u)return;u.level++;addActivity('⬆','Faction upgrade purchased',name+' · Level '+u.level);save();render();toast(name+' upgraded.')}
function toggleFactionTree(name){ensureFactionData();const a=state.faction.activeTrees;const i=a.indexOf(name);if(i>=0)a.splice(i,1);else if(a.length<6)a.push(name);else{toast('Choose up to 6 special upgrade trees.');return}save();render()}
function saveFactionProfile(){ensureFactionData();state.faction.bio=document.getElementById('factionBio')?.value.trim().slice(0,120);save();render();toast('Faction profile updated.')}
function setFactionPermission(){const id=document.getElementById('permissionPlayer')?.value.trim();const role=document.getElementById('permissionRole')?.value;if(!/^\d{7}$/.test(id)){toast('Enter a valid member ID.');return}state.faction.permissions??={};state.faction.permissions[id]=role;addActivity('⚑','Faction role changed','['+id+'] promoted to '+role);save();render();toast('Member permissions updated.')}
function factionNewsletter(){const text=document.getElementById('newsletterText')?.value.trim();if(!text){toast('Write an announcement first.');return}state.faction.newsletters.unshift({text:text.slice(0,180),time:new Date().toLocaleString()});save();render();toast('Newsletter published.')}
function createDirtyBomb(){const lab=state.faction.coreUpgrades.find(u=>u.name==='Dirty bomb lab');if(!lab||lab.level<1){toast('Upgrade the dirty bomb lab first.');return}state.faction.armory.find(i=>i.name==='Materials').qty+=1;addActivity('☢','Dirty bomb created','Stored in faction materials.');save();render();toast('Dirty bomb created.')}
function factionGive(){const id=document.getElementById('factionGivePlayer')?.value.trim();const amount=Number(document.getElementById('factionGiveAmount')?.value);if(!/^\d{7}$/.test(id)||!Number.isSafeInteger(amount)||amount<=0){toast('Enter a valid member ID and amount.');return}if(state.faction.treasury<amount){toast('Faction vault lacks those funds.');return}state.faction.treasury-=amount;state.faction.distributions??=[];state.faction.distributions.unshift({playerId:id,amount,time:new Date().toLocaleString()});addActivity('⌘','Faction vault distribution',amount.toLocaleString()+' cr → ['+id+']');save();render();toast(amount.toLocaleString()+' cr given to ['+id+'].')}
function factionChat(){const text=document.getElementById('factionChatInput')?.value.trim();if(!text)return;state.faction.chat.unshift({playerId:state.playerId,text:text.slice(0,240),time:new Date().toLocaleTimeString()});save();render()}
function startFactionEvent(type){state.faction.respect+=type==='OC'?25:10;state.faction.treasury+=type==='OC'?500:0;addActivity('⚔','Faction '+type+' started',type==='OC'?'+500 cr · +25 respect':'+10 respect');save();render();toast(type+' queued for your faction.')}
function city(){return layout(`<div class="grid grid-2"><section class="card district-map">${districts.map(d=>`<button class="district ${state.selectedDistrict===d[0]?'selected':''}" style="${d[2]}" data-district="${d[0]}">${d[0]}</button>`).join('')}</section><aside><div class="card"><div class="eyebrow">DISTRICT INTEL</div><h2>${state.selectedDistrict}</h2><p style="color:var(--muted);font-size:12px">A wet maze of container stacks and late-night markets. Good cover, volatile crews.</p><div class="resource"><span>Danger</span><b>Moderate</b></div><div class="resource"><span>Services</span><b>Gym · Jobs · Market</b></div><div class="resource"><span>Hooks</span><b>3 available</b></div><button class="btn" style="margin-top:15px" data-view="crimes">Work this district</button></div><div class="section-head"><h2>District services</h2></div><div class="list"><div class="list-row"><div><strong>Harbor gym</strong><span>Power & resilience training</span></div><span class="tag">Open</span></div><div class="list-row"><div><strong>Night market</strong><span>4 player listings</span></div><span class="tag green">Live</span></div></div></aside></div>`, 'City // Blackharbor', 'Know the streets.', 'Twelve districts. One shared city. Every shortcut has a cost.');}
function shops(){return layout(`<div class="shop-toolbar"><input id="shopSearch" placeholder="Search 32 locations…" aria-label="Search locations"/><select id="shopGroup" aria-label="Filter location category"><option value="">All categories</option>${[...new Set(shopLocations.map(s=>s[3]))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="shop-grid" id="shopGrid">${shopLocations.map(s=>`<a class="shop-card" data-shop-name="${s[1].toLowerCase()}" data-shop-group="${s[3]}" href="#${s[0]}"><img src="assets/locations/${s[0]}.png" alt="${s[1]} artwork"/><div class="shop-meta"><div><strong>${s[1]}</strong><span>${s[2]} · ${s[3]}</span></div><span class="tag">Browse →</span></div></a>`).join('')}</div>`, 'City // Services', 'Every door has a price.', 'Browse the identities of Blackharbor. Live balances and actions stay outside the artwork.');}
const shopCatalog={Equipment:[['Compact sidearm','Weapon','620'],['9mm shell pack','Ammunition','85'],['Field armor plate','Armor','340']],Supplies:[['Harbor lockpick','Tool','310'],['Utility case','Container','180'],['Work gloves','Gear','75']], 'Lifestyle & Collectibles':[['Blackharbor keepsake','Collectible','125'],['Personal accessory','Clothing','210'],['Gift parcel','Gift','95']], 'Vehicles & Travel':[['Travel provision kit','Travel supply','160'],['Performance component','Vehicle part','460'],['Cargo case','Cargo','280']], 'City Services':[['Service token','Utility','60'],['Courier parcel','Delivery','120'],['Records access pass','Access','90']], 'Markets & Trading':[['Market listing credit','Service','50'],['Appraisal voucher','Service','140'],['Trade seal','Utility','75']], 'Finance & Property':[['Secure document packet','Service','110'],['Property viewing pass','Service','200'],['Vault seal','Utility','175']]};
function shopDetail(){const s=shopLocations.find(x=>x[0]===selectedShop)||shopLocations[0];const catalog=shopCatalog[s[3]]||shopCatalog.Supplies;return layout(`<div class="shop-detail-head"><button class="btn secondary" id="backToShops">← All locations</button><span class="tag">${s[3]}</span></div><div class="shop-detail-grid"><div class="card shop-detail-art"><img src="assets/locations/${s[0]}.png" alt="${s[1]} artwork"/></div><aside class="card shop-info"><div class="eyebrow">${s[2]} // ${s[3]}</div><h2>${s[1]}</h2><p>Browse the current stock and settle purchases from your exposed wallet. Items are added to your inventory only after the balance check succeeds.</p><div class="resource"><span>Wallet</span><b>${walletLabel()}</b></div><div class="resource"><span>Stock status</span><b class="success-text">Open</b></div></aside></div><div class="section-head"><h2>Available stock</h2><p>Prices are in earned credits · server-ready purchase flow</p></div><div class="shop-stock">${catalog.map((i,n)=>`<div class="card stock-row"><div class="stock-icon"><img src="${itemAsset(i[0])}" alt="${i[0]} render"/></div><div class="stock-copy"><strong>${i[0]}</strong><span>${i[1]} · ${s[1]}</span></div><b>${money(+i[2])}</b><button class="btn shop-buy" data-item="${i[0]}" data-price="${i[2]}" data-type="${i[1]}">Buy</button></div>`).join('')}</div>`, `City // ${s[1]}`, s[1], `${s[2]} · ${s[3]}`);}
const crimeData=[['Lift a dockside parcel','Scavenging','Find an unclaimed package before the tide turns.','nerve',5,170,'⚒'],['Pocket a cardsharp','Pickpocketing','A crowded table, a clean exit, and one chance to read the room.','nerve',8,245,'♠'],['Case the shuttered arcade','Burglary','Map the cameras and choose your approach.','nerve',12,390,'⌁']];
function crimes(){return layout(`<div class="grid grid-2"><section><div class="section-head"><h2>Available opportunities</h2><p>Nerve regenerates offline · 1 / 4 min</p></div><div class="list">${crimeData.map((c,i)=>`<div class="card crime-card"><div><div class="eyebrow">${c[1]} · ${state.selectedDistrict}</div><h3>${c[0]}</h3><p>${c[2]}</p><span class="cost">${c[4]} Nerve · ~${money(c[5])}</span></div><button class="btn crime-btn" data-crime="${i}" ${state.nerve<c[4]?'disabled':''}>${i===0?'Attempt':'Plan'} →</button></div>`).join('')}</div></section><aside><div class="card"><div class="label">Crime mastery</div><div class="metric">Streetwise <small>Rank 2</small></div><div class="meter gold"><i style="width:42%"></i></div><p style="color:var(--muted);font-size:11px;margin-bottom:0">Complete different approaches to unlock cleaner exits and rare discoveries.</p></div><div class="section-head"><h2>Risk briefing</h2></div><div class="card"><p style="color:var(--muted);font-size:12px;margin:0">Heat rises when a job gets loud. Hospital and jail are recoverable states with choices; they are never a dead end.</p></div></aside></div>`, 'Operations // Crimes', 'Make a move.', 'Every job is a choice: spend Nerve, accept risk, and live with the result.');}
function gym(){return layout(`<div class="grid grid-2"><section><div class="section-head"><h2>Training floor</h2><p>${state.stamina} Stamina available</p></div><div class="list">${[['Iron Circuit','Power','Build force through compound lifts.', 'power'],['Anchor Room','Resilience','Condition your recovery and guard.', 'resilience'],['Quickstep Lab','Reflexes','Footwork drills for tight spaces.', 'reflexes'],['Range Annex','Precision','Controlled practice with moving targets.', 'precision']].map((g,i)=>`<div class="card crime-card"><div><div class="eyebrow">${g[1]}</div><h3>${g[0]}</h3><p>${g[2]}</p><strong>Current ${g[1]}: ${state[g[3]]}</strong><br><span class="cost">10 Stamina · +1 ${g[1]}</span></div><button class="btn train-btn" data-stat="${g[3]}" ${state.stamina<10?'disabled':''}>Train</button></div>`).join('')}</div></section><aside><div class="card"><div class="label">Training history</div><div class="metric">${state.trained} sessions</div><p style="color:var(--muted);font-size:12px">Each session permanently adds +1 to your selected stat and spends 10 Stamina. Stamina recovers by 1 every minute, including while away, up to ${state.maxStamina}. You can train ${Math.floor(state.stamina/10)} more times now. Progress is saved for this player in this browser.</p></div></aside></div>`, 'Progression // Gym', 'Earn your edge.', 'A stronger body buys options. It never buys certainty.');}
function inventory(){const items=state.inventory||[];return layout('<div class="card"><div class="section-head" style="margin-top:0"><h2>Items inventory</h2><p>'+items.length+' unique items · purchases saved automatically</p></div><p class="muted-note">Purchased shop items arrive here. Use consumables, track remaining uses, or sell items back for their listed resale value.</p><div class="item-grid">'+(items.map((i,n)=>{const uses=i.maxUses?((i.uses??i.maxUses)+' / '+i.maxUses):'Reusable';const sell=Math.max(1,Math.floor((i.price||100)*.55));return '<div class="item"><div class="item-icon"><img src="'+itemAsset(i.name)+'" alt="'+i.name+' render"></div><strong>'+i.name+'</strong><span>'+(i.type||i.rarity||'Item')+' · Qty '+i.qty+'</span><div class="progress">Uses: '+uses+' · Sell: '+money(sell)+'</div><div class="item-actions"><button class="btn secondary item-use" data-index="'+n+'" '+(i.maxUses&&i.uses<=0?'disabled':'')+'>Use</button><button class="btn item-sell" data-index="'+n+'">Sell</button></div></div>'}).join('')||'<div class="empty">No items yet. Browse a shop to stock your inventory.</div>')+'</div></div><div class="section-head"><h2>Item rules</h2><p>Every purchase is persisted</p></div><div class="card"><div class="list"><div class="list-row"><div><strong>Use</strong><span>Consumes one quantity or one use, depending on the item.</span></div><span class="tag green">Available</span></div><div class="list-row"><div><strong>Sell</strong><span>Returns 55% of the recorded purchase price to your wallet.</span></div><span class="tag">Market</span></div></div></div>', 'Character // Items', 'What you carry defines your exits.', 'Your purchased items, saved uses, and resale values in one place.');}const starterMissions=[
 {title:'Getting Started',desc:'Learn the core loop: train, work, study, and explore.',goals:[['Train at the gym','gym'],['Complete your first crime','crime'],['Visit the city','city']],reward:300},
 {title:'Dummy Bashing',desc:'Buy equipment, make your first attack, and spend your remaining Energy.',goals:[['Buy a weapon','weapon'],['Attack another player','attack'],['Train again','gym2']],reward:450},
 {title:'Exploring the City #1',desc:'Open the city services that keep Blackharbor moving.',goals:[['Explore Shops','shops'],['Open the Items inventory','inventory'],['Visit the Market','market']],reward:500},
 {title:'Criminal Methods',desc:'Build a criminal routine and earn from the streets.',goals:[['Complete 3 crimes','crime3'],['Earn 250 cr','cash250'],['Reach 2 heat','heat2']],reward:650},
 {title:'Guns, Ammo & Other Players',desc:'Prepare a loadout and take on a real player.',goals:[['Buy a weapon','weapon'],['Buy ammunition','ammo'],['Win an attack','attackwin']],reward:800},
 {title:'Exploring the City #2',desc:'Visit the institutions that shape the city.',goals:[['Visit the hospital','hospital'],['Visit the factions','factions'],['Visit the city bank','bank']],reward:900},
 {title:'Effective Stat Building',desc:'Raise your core combat stats through consistent training.',goals:[['Raise Power to 12','power12'],['Raise Resilience to 12','resilience12'],['Raise any stat to 15','stat15']],reward:1100},
 {title:'Exploring the City #3',desc:'Find the communities and records behind the city.',goals:[['Explore Hall of Fame','hall'],['Visit the Market','market2'],['Visit Missions','missions']],reward:1200},
 {title:'Well on Your Way',desc:'Secure equipment, property, awards, and your first level.',goals:[['Buy armor','armor'],['Earn an attack award','award'],['Reach level 2','level2']],reward:1500}
];
function missionDone(id){const items=state.inventory||[];const views=state.visitedViews||{};switch(id){case'gym':return state.trained>0;case'gym2':return state.trained>1;case'crime':return state.crimes>0;case'crime3':return state.crimes>=3;case'city':return !!views.city;case'shops':return !!views.shops;case'inventory':return !!views.inventory;case'market':case'market2':return !!views.market;case'weapon':return items.some(i=>i.type==='Weapon'||/sidearm|gun|weapon/i.test(i.name));case'ammo':return items.some(i=>i.type==='Ammunition'||/ammo|shell/i.test(i.name));case'attack':return (state.attacks||0)>0;case'attackwin':return (state.attackWins||0)>0;case'cash250':return state.cash>=250;case'heat2':return state.heat>=2;case'hospital':case'bank':return !!views.city;case'factions':return !!views.factions;case'power12':return state.power>=12;case'resilience12':return state.resilience>=12;case'stat15':return Math.max(state.power,state.resilience,state.reflexes,state.precision)>=15;case'hall':return !!views.hall;case'missions':return !!views.missions;case'armor':return items.some(i=>i.type==='Armor'||/armor/i.test(i.name));case'award':return (state.awards||[]).length>0;case'level2':return state.level>=2;default:return false}}
function missions(){const active=Math.min(state.completedMissions||0,starterMissions.length-1);return layout(`<div class="grid grid-2"><section><div class="card"><div class="eyebrow">NEW PLAYER GUIDE // ${active+1} OF ${starterMissions.length}</div><h2>${starterMissions[active].title}</h2><p class="muted-note">${starterMissions[active].desc}</p><div class="list">${starterMissions[active].goals.map(g=>`<div class="list-row"><div><strong>${g[0]}</strong><span>${missionDone(g[1])?'Objective complete':'Still to do'}</span></div><span class="tag ${missionDone(g[1])?'green':''}">${missionDone(g[1])?'✓':'Open'}</span></div>`).join('')}</div>${starterMissions[active].goals.every(g=>missionDone(g[1]))?'<button class="btn" id="claimMission" style="margin-top:15px">Claim '+money(starterMissions[active].reward)+' + XP</button>':'<p class="muted-note" style="margin-top:15px">Complete every objective to unlock the reward.</p>'}</div></section><aside><div class="card"><div class="label">Mission track</div><div class="metric">${state.completedMissions||0} / ${starterMissions.length}</div><div class="meter"><i style="width:${(state.completedMissions||0)/starterMissions.length*100}%"></i></div><p class="muted-note">Missions guide your first days in Blackharbor. Rewards are saved when claimed.</p></div><div class="list">${starterMissions.map((m,i)=>`<div class="list-row"><div><strong>${i+1}. ${m.title}</strong><span>${i<(state.completedMissions||0)?'Completed':i===active?'Current':'Locked'}</span></div><span class="tag ${i<(state.completedMissions||0)?'green':''}">${i<(state.completedMissions||0)?'✓':i===active?'Live':'Locked'}</span></div>`).join('')}</div></aside></div>`, 'Progression // New Player Missions', 'Start your journey.', 'A guided route through the gym, jobs, shops, city, combat, and faction life.');}
function market(){return layout(`<div class="card"><div class="section-head" style="margin-top:0"><h2>Night market</h2><p>Shared Blackharbor listings · refreshed 2m ago</p></div><div class="list"><div class="list-row"><div><strong>Field wrap</strong><span>Consumable · Common · Seller: Dockhand_12</span></div><b>${money(95)}</b><button class="btn secondary buy-btn" data-price="95">Buy</button></div><div class="list-row"><div><strong>Compact sidearm</strong><span>Weapon · Uncommon · Seller: redline</span></div><b>${money(620)}</b><button class="btn secondary buy-btn" data-price="620">Buy</button></div><div class="list-row"><div><strong>Harbor lockpick</strong><span>Tool · Uncommon · Seller: Mara’s runner</span></div><b>${money(310)}</b><button class="btn secondary buy-btn" data-price="310">Buy</button></div></div></div><div class="section-head"><h2>Price signals</h2></div><div class="grid grid-4"><div class="card"><div class="label">Field wrap</div><div class="metric">−4.2%</div></div><div class="card"><div class="label">9mm shells</div><div class="metric">+8.1%</div></div><div class="card"><div class="label">Lockpicks</div><div class="metric">+1.7%</div></div><div class="card"><div class="label">Listings</div><div class="metric">184</div></div></div>`, 'Economy // Market', 'Buy carefully.', 'Prices are shared, fees are visible, and settlement is atomic.');}
function hall(){const players=readPlayerIndex().filter(p=>/^\d{7}$/.test(String(p.playerId)));if(activePlayerId&&state.playerId&&!players.some(p=>p.playerId===String(state.playerId)))registerPlayer(state);const ranked=readPlayerIndex().sort((a,b)=>(b.level-a.level)||(b.xp-a.xp)||a.name.localeCompare(b.name));return layout(`<div class="card"><div class="section-head"><h2>Player leaderboard</h2><p>${ranked.length} registered players</p></div><p class="muted-note">Every verified player appears here. Search a real player name or ID, then open their public profile.</p><input id="playerSearch" class="name-input" placeholder="Search player name or ID" autocomplete="off"><div class="list" id="playerList">${ranked.map((p,i)=>`<div class="list-row player-row" data-player-search="${p.name.toLowerCase()} ${p.playerId}"><div><strong>#${i+1} · ${p.name} <span>[${p.playerId}]</span></strong><span>Level ${p.level} · ${p.faction||'Unaffiliated'}</span></div><a class="btn secondary profile-open" href="/profiles.php?XID=${p.playerId}" data-xid="${p.playerId}">View profile</a></div>`).join('')||'<div class="empty">No verified player profiles are available yet.</div>'}</div></div>`, 'Community // Hall of Fame', 'The city remembers names.', 'Find players, inspect their public profile, and choose your next move.');}
function publicProfile(){const p=findPlayer(publicProfileId);if(!p)return layout('<div class="card empty">No player exists with that ID.</div>','Community // Player Search','Player not found','Check the numeric player ID and try again.');const own=String(p.playerId)===String(state.playerId);const avatar=p.avatarUrl?`<img class="avatar-image" src="${p.avatarUrl}" alt="${p.name} avatar"/>`:`<div class="portrait-large">${p.name.slice(0,2).toUpperCase()}</div>`;return layout(`<div class="profile-identity"><div class="presence-dot online"></div><div><h2>${p.name} <span>[${p.playerId}]</span></h2><p>Public player profile</p></div><span class="tag">LEVEL ${p.level}</span></div><div class="profile-grid"><section class="card profile-portrait">${avatar}</section><section class="card profile-core"><div class="panel-title">Player information</div><div class="profile-level"><strong>Level ${p.level}</strong><span>${p.xp} XP</span></div><div class="resource"><span>Faction</span><b>${p.faction||'Unaffiliated'}</b></div><div class="resource"><span>Player ID</span><b>${p.playerId}</b></div></section><section class="card profile-actions"><div class="panel-title">Actions</div>${own?'<p class="muted-note">This is your own profile. Attack is unavailable.</p>':'<button class="btn attack-btn" data-attack="'+p.playerId+'">⚔ Attack player</button><p class="muted-note">Costs 25 Energy · up to 25 turns · five-minute fight window.</p>'}</section></div><div class="card"><div class="panel-title">Profile link</div><code>/profiles.php?XID=${p.playerId}</code></div>`, 'Community // Player Profile', `${p.name} [${p.playerId}]`, own?'Your public profile.':'Choose whether to make a move against this player.');}
const attackBodyParts=[['Head',3.5,true],['Throat',3.5,true],['Heart',3.5,true],['Chest',2,false],['Stomach',2,false],['Groin',2,false],['Left arm',1,false],['Right arm',1,false],['Left hand',.7,false],['Right hand',.7,false],['Left leg',1,false],['Right leg',1,false],['Left foot',.7,false],['Right foot',.7,false]];
const attackAwards=[['Kill Streaker 1',s=>(s.killStreak||0)>=10],['Chainer 1',s=>(s.chain||0)>=10],['Carnage',s=>(s.lastAttack?.respect||0)>=10],['Flatline',s=>s.lastAttack?.oneHitKill===true]];
function attackPlayer(id){if(String(id)===String(state.playerId)){toast('You cannot attack yourself.');return}if(!spend('stamina',25)){toast('You need 25 Energy to attack.');return}const critical=Math.random()<.12;const pool=critical?attackBodyParts.filter(x=>x[2]):attackBodyParts.filter(x=>!x[2]);const hit=pool[Math.floor(Math.random()*pool.length)];const baseDamage=Math.floor(8+Math.random()*13);const damage=Math.max(1,Math.round(baseDamage*hit[1]));const won=Math.random()<.62;state.attacks=(state.attacks||0)+1;state.lastAttack={targetId:String(id),bodyPart:hit[0],critical:hit[2],damage,respect:won?Math.floor(1+Math.random()*12):0,oneHitKill:won&&damage>=40,won,at:Date.now()};if(won){state.attackWins=(state.attackWins||0)+1;state.killStreak=(state.killStreak||0)+1;state.chain=(state.chain||0)+1}else{state.killStreak=0;state.chain=0}const unlocked=[];for(const [name,test] of attackAwards)if(test(state)&&!(state.awards||[]).includes(name)){state.awards=[...(state.awards||[]),name];unlocked.push(name)}addActivity(won?'⚔':'🛡',won?'Attack won':'Attack lost',`${hit[0]}${hit[2]?' · Critical':''} · ${damage} damage · 25 Energy`);save();toast(`${won?'Victory':'Defeat'} · ${hit[0]}${hit[2]?' critical':''} · ${damage} damage${unlocked.length?' · Award: '+unlocked.join(', '):''}`);render()}
const companyTypes=[['Candle Shop',500000,4],['Flower Shop',500000,4],['Hair Salon',750000,4],['Property Broker',750000,4],['Clothing Store',1000000,5],['Restaurant',1000000,4],['Game Shop',1250000,4],['Pub',1250000,4],['Music Store',1500000,4],['Cyber Cafe',3000000,4],['Mechanic Shop',3000000,4],['Law Firm',4000000,4],['Farm',5250000,5],['Nightclub',7500000,5],['Detective Agency',12000000,4],['Fitness Center',17000000,8],['Gas Station',25000000,4],['Amusement Park',100000000,8],['Private Security Firm',950000000,6],['Logistics Management',1800000000,6],['Mining Corporation',4500000000,8],['Oil Rig',10500000000,12]];
function companyDefault(type,cost,size){return {type,cost,size,employees:[],vault:0,advertising:0,popularity:0,efficiency:100,environment:100,stars:1,jobPoints:0,stock:0,upgrades:{size:0,staffRoom:0,warehouse:0},applications:[]}}
function companies(){if(!state.company)return layout(`<div class="card"><div class="eyebrow">BUSINESS // ACQUISITION</div><h2>Start or join a company</h2><p class="muted-note">You need level 10 and the startup cost to become a director. Players level 3 and above can apply as employees.</p><div class="grid grid-3">${companyTypes.map(c=>`<article class="card company-card"><h3>${c[0]}</h3><div class="metric">${money(c[1])}</div><p>${c[2]} employee capacity · Default settings</p><button class="btn start-company" data-company="${c[0]}" data-cost="${c[1]}" data-size="${c[2]}" ${state.level<10||(!isOwner()&&state.cash<c[1])?'disabled':''}>Start company</button></article>`).join('')}</div></div>`, 'Economy // Companies', 'Build a business.', 'Player-owned companies turn cooperation, staffing, stock, and management into a second economy.');const c=state.company;return layout(`<div class="profile-identity"><div><h2>${c.type}</h2><p>Director: ${state.name} [${state.playerId}]</p></div><span class="tag green">${c.stars} ★ COMPANY</span></div><div class="grid grid-4"><div class="card"><div class="label">Popularity</div><div class="metric">${c.popularity}%</div></div><div class="card"><div class="label">Efficiency</div><div class="metric">${c.efficiency}%</div></div><div class="card"><div class="label">Environment</div><div class="metric">${c.environment}%</div></div><div class="card"><div class="label">Vault</div><div class="metric">${money(c.vault)}</div></div></div><div class="grid grid-2"><section class="card"><div class="panel-title">Employees <span class="tag">${c.employees.length} / ${c.size}</span></div><p class="muted-note">Assign positions, budget pay, and train employees. New hires have a 72-hour recruit restriction.</p><div class="list">${c.employees.map(e=>`<div class="list-row"><div><strong>${e.name}</strong><span>${e.position||'Unassigned'} · Effectiveness ${e.effectiveness||0}%</span></div><span class="tag">${e.pay||0} cr</span></div>`).join('')||'<div class="empty">No employees yet. Applications will appear here.</div>'}</div><div class="form-row"><input id="companyEmployeeId" class="name-input" placeholder="Player ID"><button class="btn" id="hireEmployee">Hire employee</button></div></section><aside><div class="card"><div class="panel-title">Director controls</div><div class="form-row"><label>Daily advertising</label><input id="companyAds" class="name-input" type="number" min="0" value="${c.advertising}"><button class="btn" id="saveCompanyAds">Save budget</button></div><div class="form-row"><label>Deposit to vault</label><input id="companyDeposit" class="name-input" type="number" min="0" placeholder="Credits"><button class="btn secondary" id="depositCompany">Deposit</button></div></div><div class="card"><div class="panel-title">Upgrades</div><div class="list"><div class="list-row"><div><strong>Company size</strong><span>${c.size} capacity · Upgrade ${c.upgrades.size+1}</span></div><button class="btn company-upgrade" data-upgrade="size">Upgrade</button></div><div class="list-row"><div><strong>Staff room</strong><span>Environment support · Level ${c.upgrades.staffRoom}</span></div><button class="btn company-upgrade" data-upgrade="staffRoom">Upgrade</button></div><div class="list-row"><div><strong>Warehouse</strong><span>Stock capacity · Level ${c.upgrades.warehouse}</span></div><button class="btn company-upgrade" data-upgrade="warehouse">Upgrade</button></div></div></div></aside></div>`, 'Economy // Company Director', c.type, 'Micromanage people, stock, advertising, and the vault to grow your ranking.');}
function createCompany(e){const b=e?.currentTarget;const type=b?.dataset.company,cost=Number(b?.dataset.cost),size=Number(b?.dataset.size);if(state.level<10&&!isOwner()){toast('You must be level 10 to own a company.');return}if(!isOwner()&&state.cash<cost){toast('You need more credits for this startup.');return}if(!isOwner())state.cash-=cost;state.company=companyDefault(type,cost,size);addActivity('▥','Company founded',type);save();render();toast(`${type} founded.`)}
function hireEmployee(){const id=document.getElementById('companyEmployeeId')?.value.trim();if(!/^\d{7}$/.test(id)){toast('Enter a valid 7-digit player ID.');return}if(state.company.employees.length>=state.company.size){toast('Your company is at capacity.');return}state.company.employees.push({playerId:id,name:`Player [${id}]`,position:'Unassigned',pay:0,effectiveness:50,hiredAt:Date.now()});save();render();toast('Employee hired as Unassigned.')}
function saveCompanyAds(){const amount=Math.max(0,Number(document.getElementById('companyAds')?.value)||0);state.company.advertising=amount;state.company.popularity=Math.min(100,Math.floor(amount/1000));save();render();toast('Advertising budget updated.')}
function depositCompany(){const amount=Math.floor(Number(document.getElementById('companyDeposit')?.value)||0);if(amount<=0||(!isOwner()&&state.cash<amount)){toast('Enter an amount available in your wallet.');return}if(!isOwner())state.cash-=amount;state.company.vault+=amount;save();render();toast('Funds deposited into the company vault.')}
function companyUpgrade(kind){const cost=Math.floor(state.company.cost*(0.1+state.company.upgrades[kind]*0.1));if(!isOwner()&&state.cash<cost){toast(`You need ${money(cost)} for this upgrade.`);return}if(!isOwner())state.cash-=cost;state.company.upgrades[kind]++;if(kind==='size')state.company.size=Math.ceil(state.company.size*1.25);if(kind==='staffRoom')state.company.environment=Math.min(100,state.company.environment+5);state.company.stock+=kind==='warehouse'?10:0;save();render();toast(`${kind} upgrade purchased.`)}
const honorCatalog=[
 {name:'Blackharbor Citizen',category:'Default',default:true,req:'Available to every player.'},{name:'Verified Operative',category:'Default',default:true,req:'Google account verified.'},{name:'Kill Streaker 1',category:'Attacking',req:'Achieve a 10 kill streak.',test:s=>(s.killStreak||0)>=10},{name:'Chainer 1',category:'Chaining',req:'Participate in a 10 length chain.',test:s=>(s.chain||0)>=10},{name:'Carnage',category:'Attacking',req:'Earn 10 respect from one hit.',test:s=>(s.lastAttack?.respect||0)>=10},{name:'Flatline',category:'Attacking',req:'Achieve a one-hit kill.',test:s=>s.lastAttack?.oneHitKill===true},{name:'First Steps',category:'Missions',req:'Complete your first new-player mission.',test:s=>(s.completedMissions||0)>=1},{name:'Street Operator',category:'Crimes',req:'Complete 10 crimes.',test:s=>(s.crimes||0)>=10},{name:'Gym Rat',category:'Gyms & Stats',req:'Complete 10 training sessions.',test:s=>(s.trained||0)>=10},{name:'Level Climber',category:'Leveling',req:'Reach level 5.',test:s=>(s.level||0)>=5},{name:'Market Regular',category:'Money & Trading',req:'Own 5 different items.',test:s=>(s.inventory||[]).length>=5},{name:'Faction Founder',category:'Factions',req:'Create or join a faction.',test:s=>!!s.faction},{name:'Hall Regular',category:'Miscellaneous',req:'Visit the Hall of Fame.',test:s=>!!s.visitedViews?.hall},{name:'Blackharbor Survivor',category:'Commitment',req:'Accumulate one day of active play time.',test:s=>(s.onlineSeconds||0)>=86400}];
function awards(){const earned=honorCatalog.filter(h=>h.default||h.test?.(state));const earnedNames=new Set(earned.map(h=>h.name));const categories=['All',...new Set(honorCatalog.map(h=>h.category))];return layout(`<div class="card"><div class="section-head"><h2>Honors & medals</h2><p>${earned.length} earned · 347 honor bars tracked</p></div><p class="muted-note">Earn honors by completing challenges across Blackharbor. Default honors are available to every player; earned honors and medals are permanently recorded.</p><div class="award-filters">${categories.map(c=>`<button class="tag award-filter ${c==='All'?'green':''}" data-award-category="${c}">${c}</button>`).join('')}</div><div class="award-grid">${honorCatalog.map(h=>`<article class="card award-card ${earnedNames.has(h.name)?'earned':''}" data-award-category="${h.category}"><div class="award-icon">${earnedNames.has(h.name)?'🏅':'◇'}</div><div><h3>${h.name}</h3><span class="tag">${h.category}</span><p>${h.req}</p><strong>${earnedNames.has(h.name)?'Earned':'Locked'}</strong></div></article>`).join('')}</div></div>`, 'Character // Honors', 'Earn your name.', 'Honor bars and medals record the challenges you survive, the risks you take, and the time you put into the city.');}

const views={overview,profile,factions,owner:ownerCheats,city,shops,shop:shopDetail,crimes,gym,inventory,missions,market,companies,hall,awards,publicProfile};
function render(){if(activePlayerId&&recoverStamina())save();document.getElementById('main').innerHTML=views[view]();const playerSearch=document.getElementById('playerSearch');if(playerSearch)playerSearch.oninput=()=>document.querySelectorAll('[data-player-search]').forEach(row=>row.hidden=!row.dataset.playerSearch.includes(playerSearch.value.toLowerCase().trim()));document.querySelectorAll('.award-filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.award-filter').forEach(x=>x.classList.toggle('green',x===b));document.querySelectorAll('.award-card').forEach(card=>card.hidden=b.dataset.awardCategory!=='All'&&card.dataset.awardCategory!==b.dataset.awardCategory)});document.querySelectorAll('.start-company').forEach(b=>b.onclick=e=>createCompany(e));const hireEmployeeBtn=document.getElementById('hireEmployee');if(hireEmployeeBtn)hireEmployeeBtn.onclick=hireEmployee;const saveAds=document.getElementById('saveCompanyAds');if(saveAds)saveAds.onclick=saveCompanyAds;const deposit=document.getElementById('depositCompany');if(deposit)deposit.onclick=depositCompany;document.querySelectorAll('.company-upgrade').forEach(b=>b.onclick=()=>companyUpgrade(b.dataset.upgrade));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='profile'&&window.openProfilePage)return window.openProfilePage();state.visitedViews={...(state.visitedViews||{}),[b.dataset.view]:true};save();view=b.dataset.view;render()});document.querySelectorAll('.district').forEach(b=>b.onclick=()=>{state.selectedDistrict=b.dataset.district;save();render()});document.querySelectorAll('.profile-open').forEach(b=>b.onclick=e=>{e.preventDefault();publicProfileId=b.dataset.xid;history.pushState({},'',`/profiles.php?XID=${publicProfileId}`);view='publicProfile';render()});document.querySelectorAll('.attack-btn').forEach(b=>b.onclick=()=>attackPlayer(b.dataset.attack));document.querySelectorAll('.crime-btn').forEach(b=>b.onclick=()=>doCrime(+b.dataset.crime));document.querySelectorAll('.train-btn').forEach(b=>b.onclick=()=>train(b.dataset.stat));document.querySelectorAll('.buy-btn').forEach(b=>b.onclick=()=>buy(+b.dataset.price));document.querySelectorAll('.item-use').forEach(b=>b.onclick=()=>useItem(+b.dataset.index));document.querySelectorAll('.item-sell').forEach(b=>b.onclick=()=>sellItem(+b.dataset.index));document.querySelectorAll('.shop-card').forEach(b=>b.onclick=e=>{e.preventDefault();selectedShop=b.dataset.shopName?shopLocations.find(s=>s[1].toLowerCase()===b.dataset.shopName).at(0):null;selectedShop=shopLocations.find(s=>s[1].toLowerCase()===b.dataset.shopName)[0];view='shop';render()});document.querySelectorAll('.shop-buy').forEach(b=>b.onclick=()=>buyShopItem(b.dataset.item,+b.dataset.price,b.dataset.type));const back=document.getElementById('backToShops');if(back)back.onclick=()=>{view='shops';render()};const avatarInput=document.getElementById('avatarInput');if(avatarInput)avatarInput.onchange=e=>handleAvatarUpload(e.target.files[0]);const claim=document.getElementById('claimMission');if(claim)claim.onclick=claimMission;const createFactionBtn=document.getElementById('createFaction');if(createFactionBtn)createFactionBtn.onclick=createFaction;const inviteBtn=document.getElementById('inviteBtn');if(inviteBtn)inviteBtn.onclick=inviteToFaction;document.querySelectorAll('.faction-tab').forEach(b=>b.onclick=()=>{window.factionTab=b.dataset.factionTab;render()});const armoryAction=document.getElementById('armoryAction');if(armoryAction)armoryAction.onclick=factionAction;document.querySelectorAll('.upgrade-btn').forEach(b=>b.onclick=()=>factionUpgrade(b.dataset.upgrade));document.querySelectorAll('.tree-btn').forEach(b=>b.onclick=()=>toggleFactionTree(b.dataset.tree));const saveFaction=document.getElementById('saveFactionProfile');if(saveFaction)saveFaction.onclick=saveFactionProfile;const setPermission=document.getElementById('setPermission');if(setPermission)setPermission.onclick=setFactionPermission;const newsletterBtn=document.getElementById('newsletterBtn');if(newsletterBtn)newsletterBtn.onclick=factionNewsletter;const dirtyBombBtn=document.getElementById('dirtyBombBtn');if(dirtyBombBtn)dirtyBombBtn.onclick=createDirtyBomb;const factionGiveBtn=document.getElementById('factionGiveBtn');if(factionGiveBtn)factionGiveBtn.onclick=factionGive;const factionChatBtn=document.getElementById('factionChatBtn');if(factionChatBtn)factionChatBtn.onclick=factionChat;const startOcBtn=document.getElementById('startOcBtn');if(startOcBtn)startOcBtn.onclick=()=>startFactionEvent('OC');const startRwBtn=document.getElementById('startRwBtn');if(startRwBtn)startRwBtn.onclick=()=>startFactionEvent('RW');const grantBtn=document.getElementById('grantBtn');if(grantBtn)grantBtn.onclick=grantCredits;const shopSearch=document.getElementById('shopSearch');const shopGroup=document.getElementById('shopGroup');if(shopSearch&&shopGroup){const filter=()=>document.querySelectorAll('.shop-card').forEach(c=>{c.hidden=!(c.dataset.shopName.includes(shopSearch.value.toLowerCase())&&(!shopGroup.value||c.dataset.shopGroup===shopGroup.value))});shopSearch.oninput=filter;shopGroup.onchange=filter}document.getElementById('navName').textContent=`${state.name} [${state.playerId}]`;document.getElementById('navLevel').textContent=state.role==='owner'?'OWNER':state.level;document.querySelectorAll('.owner-only-nav').forEach(b=>b.hidden=!isOwner());document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function doCrime(i){const c=crimeData[i];if(!spend('nerve',c[4]))return;const success=Math.random()>.25;state.crimes++;state.heat=Math.min(100,state.heat+(success?3:7));if(success){state.cash+=c[5];state.xp+=12;addActivity('⚒',`${c[0]} completed`, `You got out with ${money(c[5])}`);toast(`Job complete. +${money(c[5])}`)}else{state.vitality=Math.max(1,state.vitality-8);addActivity('!',`${c[0]} went sideways`,'You escaped with a bruised rib.');toast('Clean failure. Keep your head down.')}save();render()}
function train(stat){
 if(!activePlayerId||!TRAINING_STATS.includes(stat))return;
 // Reload before spending so another open tab cannot overwrite a previous session.
 const previous=structuredClone(state);
 try{
  const latest=JSON.parse(localStorage.getItem(playerSaveKey(activePlayerId))||'null');
  if(latest)state=latest;
  recoverStamina();
  if(!spend('stamina',10)){save();render();return}
  state[stat]++;state.trained++;state.xp+=5;
  addActivity('✦','Training complete',`+1 ${stat[0].toUpperCase()+stat.slice(1)} · 10 Stamina`);
  save();
 }catch(error){state=previous;toast('Training could not be saved. Please free browser storage and try again.');render();return}
 toast(`Saved: +1 ${stat}. ${state.stamina} Stamina remaining.`);render();
}
function addInventoryItem(name,price,type,icon='◈'){const existing=state.inventory.find(i=>i.name===name);if(existing){existing.qty++;if(existing.maxUses)existing.uses=existing.maxUses}else{const maxUses=type==='Ammunition'?1:type==='Tool'?5:type==='Weapon'?20:type==='Armor'?30:3;state.inventory.push({id:'item-'+name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),name,icon,qty:1,rarity:'Common',type,price,maxUses,uses:maxUses})}}
function buy(price){if(!isOwner()&&state.cash<price){toast('Not enough cash.');return}if(!isOwner())state.cash-=price;addInventoryItem('Market purchase',price,'Market item','◫');addActivity('⌘','Market purchase',`Settled atomically for ${money(price)}`);toast('Purchase saved to Items inventory.');save();render()}
function buyShopItem(name,price,type){if(!isOwner()&&state.cash<price){toast(`Not enough cash for ${name}.`);return}if(!isOwner())state.cash-=price;addInventoryItem(name,price,type);const shop=shopLocations.find(s=>s[0]===selectedShop);addActivity('⌘',`${name} purchased`,`${shop?.[1]||'Shop'} · ${money(price)}`);toast(`${name} saved to Items inventory.`);save();render()}
function useItem(index){const item=state.inventory[index];if(!item)return;if(item.maxUses&&item.uses<=0){toast('This item has no uses remaining.');return}if(item.maxUses)item.uses--;else item.qty--;if(item.qty<=0){state.inventory.splice(index,1);toast(`${item.name} used up.`)}else toast(`${item.name} used.`);addActivity('◈','Item used',item.name);save();render()}
function sellItem(index){const item=state.inventory[index];if(!item)return;const value=Math.max(1,Math.floor((item.price||100)*.55));state.cash+=value;item.qty--;if(item.qty<=0)state.inventory.splice(index,1);addActivity('⌘','Item sold',`${item.name} · +${money(value)}`);toast(`${item.name} sold for ${money(value)}.`);save();render()}
function grantCredits(){if(!isOwner()){toast('Owner access required.');return}const playerId=document.getElementById('grantPlayerId')?.value.trim();const amount=Number(document.getElementById('grantAmount')?.value);if(!/^\d{7}$/.test(playerId)){toast('Enter a valid 7-digit player ID.');return}if(!Number.isSafeInteger(amount)||amount<=0){toast('Enter a positive whole credit amount.');return}state.ownerGrants.unshift({playerId,amount,grantedAt:new Date().toLocaleString()});addActivity('♛','Owner credit grant',`${amount.toLocaleString()} cr granted to [${playerId}]`);save();render();toast(`${amount.toLocaleString()} cr granted to [${playerId}].`)}
function handleAvatarUpload(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Use a JPG, PNG, or WebP image.');return}if(file.size>5*1024*1024){toast('Avatar must be 5 MB or smaller.');return}const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=666;canvas.height=916;const scale=Math.max(666/image.width,916/image.height);const w=image.width*scale,h=image.height*scale;const ctx=canvas.getContext('2d');ctx.fillStyle='#10161d';ctx.fillRect(0,0,666,916);ctx.drawImage(image,(666-w)/2,(916-h)/2,w,h);state.avatarUrl=canvas.toDataURL('image/jpeg',.82);state.avatarModeration='pending';addActivity('◉','Avatar uploaded','Pending safety review · normalized to 666 × 916');save();toast('Avatar uploaded and queued for safety review.');render()};image.onerror=()=>toast('That image could not be read.');image.src=reader.result};reader.readAsDataURL(file)}
function claimMission(){if((state.completedMissions||0)>=starterMissions.length){toast('All new player missions are complete.');return}const mission=starterMissions[Math.min(state.completedMissions||0,starterMissions.length-1)];if(!mission||!mission.goals.every(g=>missionDone(g[1])))return;state.cash+=mission.reward;state.xp+=20;state.completedMissions=(state.completedMissions||0)+1;addActivity('◆','Mission completed',mission.title);toast(`Mission complete. +${money(mission.reward)} +20 XP`);save();render()}
window.openProfilePage=()=>{view='profile';document.getElementById('authGate').classList.add('hidden');try{render()}catch(error){console.error('[gore-wars] profile render failed',error);document.getElementById('main').innerHTML=layout('<div class="card empty">Profile could not be rendered: '+error.message+'</div>','Character // Profile','Profile unavailable','The profile view encountered a rendering error.')}};
document.getElementById('signOutBtn').onclick=()=>{save();localStorage.removeItem(AUTH_KEY);window.location.href='/api/auth/signout'};
document.getElementById('googleSignIn').onclick=()=>{window.location.href='/api/auth/google/start'};
document.getElementById('commandBtn').onclick=()=>{document.getElementById('commandModal').classList.remove('hidden');document.getElementById('commandInput').focus()};
document.getElementById('closeCommand').onclick=()=>document.getElementById('commandModal').classList.add('hidden');
document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{view=b.dataset.command;document.getElementById('commandModal').classList.add('hidden');render()});
document.getElementById('resetBtn').onclick=()=>{if(confirm('Reset local progression?')){if(activePlayerId)localStorage.removeItem(playerSaveKey(activePlayerId));activePlayerId=null;localStorage.removeItem(SAVE_KEY);localStorage.removeItem(AUTH_KEY);state=load();view='overview';render();document.getElementById('authGate').classList.remove('hidden');toast('Save reset.')}};
document.querySelector('.avatar').onclick=()=>document.getElementById('authGate').classList.remove('hidden');
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.getElementById('commandBtn').click()}});
try{render()}catch(error){console.error('[gore-wars] startup render failed',error)}
const authSuccess=new URLSearchParams(location.search).get('auth')==='success';
if(authSuccess){fetch('/api/auth/me').then(r=>r.ok?r.json():null).then(result=>{if(result?.authenticated){restorePlayer(result.player);localStorage.setItem(AUTH_KEY,'google');history.replaceState({},'',location.pathname);document.getElementById('authGate').classList.add('hidden');try{render()}catch(error){console.error('[gore-wars] authenticated render failed',error)}toast(`Signed in as ${state.name} [${state.playerId}]`)}}).catch(error=>console.error('[gore-wars] session lookup failed',error))}else if(localStorage.getItem(AUTH_KEY)==='google'){fetch('/api/auth/me').then(r=>r.ok?r.json():null).then(result=>{if(result?.authenticated){restorePlayer(result.player);document.getElementById('authGate').classList.add('hidden');render()}else{localStorage.removeItem(AUTH_KEY)}}).catch(()=>localStorage.removeItem(AUTH_KEY))}else if(localStorage.getItem(AUTH_KEY)==='demo')document.getElementById('authGate').classList.add('hidden');

let lastPresenceSave=0,lastAgeRender=0;
setInterval(()=>{if(!activePlayerId)return;const now=Date.now();checkpointPresence(now);if(now-lastPresenceSave>10000){try{save();lastPresenceSave=now}catch{toast('Presence could not be saved.')}}if(recoverStamina(now)){try{save();lastPresenceSave=now;render()}catch{toast('Stamina could not be saved.')}}if(view==='profile'&&now-lastAgeRender>30000){lastAgeRender=now;render()}},1000);
window.addEventListener('storage',event=>{
 if(activePlayerId&&event.key===playerSaveKey(activePlayerId)&&event.newValue){
  try{state={...state,...JSON.parse(event.newValue)};render()}catch{}
 }
});

window.addEventListener('pagehide',endPresence);document.addEventListener('visibilitychange',()=>{if(document.hidden)endPresence();else if(activePlayerId&&!state.onlineSince){startPresence();save();render()}});

window.addEventListener('popstate',()=>{publicProfileId=new URLSearchParams(location.search).get('XID');view=publicProfileId?'publicProfile':'overview';render()});
